    `<div class="tabs">${FUND_TABS.map(([k,l])=>`<button class="tab${tab===k?' on':''}" data-ft="${k}">${l}</button>`).join('')}</div><div id="feBody" class="stack"></div>`;
  $('feBack').onclick=()=>go('fund'); $('feEdit').onclick=()=>fundEventDrawer(e); const pb=$('fePub'); if(pb) pb.onclick=()=>fundPublish(e); const op=$('feOpen'); if(op) op.onclick=()=>fundLinkDrawer(e);
