function levelDrawer(e,l){ const isNew=!l; l=l||{id:uid(),name:'',amount:0,perks:''}; openDrawer({kicker:e.name,title:isNew?'Sponsorship level':l.name,del:isNew?null:()=>{ e.levels=e.levels.filter(x=>x.id!==l.id); persist(); pushFund(e); },body:pair(field('Level','lvN',l.name,{ph:'Gold'}),field('Amount $','lvA',l.amount,{type:'number'}))+field('What it includes','lvP',l.perks,{type:'textarea'}),save:()=>{ l.name=fv('lvN').trim(); if(!l.name){ toast('Name the level'); return false; } l.amount=n0(fv('lvA')); l.perks=fv('lvP'); if(isNew) e.levels.push(l); persist(); pushFund(e); }}); }
