/* ---- Raffles: tickets by paddle, a legitimate drawing ---- */
function ftRaffles(m,e,S){ m.innerHTML=`<div class="toolbar" style="justify-content:flex-end"><button class="btn sm pri" id="rfNew">${I.plus}Raffle</button></div>`+(e.raffles.map(r=>{ const sold=r.tickets.reduce((a,t)=>a+t.qty,0), take=n0(r.price)*sold; return `<div class="card lg" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">${esc(r.name)}</h2><span class="muted">${fmt2(r.price)} a ticket · ${sold} sold · ${fmt2(take)}</span></div><div class="actions"><button class="btn sm" data-rfe="${r.id}">${I.edit}Edit</button>${r.locked?`<span class="chip ok">Locked · ${r.locked.count} tickets · ${esc(r.locked.fp.slice(0,8))}</span><button class="btn sm" data-rfu="${r.id}">Unlock…</button>`:`<button class="btn sm" data-rfs="${r.id}">Sell tickets</button>${sold?`<button class="btn sm" data-rfl="${r.id}">Lock the list</button>`:''}`}${r.locked&&r.prizes.some(p=>!p.winner)?`<button class="btn sm pri" data-rfd="${r.id}">Draw</button>`:''}${r.tickets.length?`<button class="btn sm" data-rfr="${r.id}">${I.down}Record</button>`:''}</div></div>
      <div class="grid g2" style="padding:0 22px 16px"><div><b>Prizes</b>${r.prizes.map((p,i)=>`<div class="lr" style="padding:6px 0"><div class="cell2"><span class="ln">${i+1}. ${esc(p.name)}</span><span class="ls">${p.winner?`won by ${esc(p.winner.name)} · ticket ${p.winner.ticket} · ${new Date(p.winner.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})} · <a href="#" data-rfv="${r.id}|${p.id}">void</a>`:n0(p.value)?'value '+fmt2(p.value):''}</span></div></div>`).join('')||'<p class="muted">No prizes yet.</p>'}</div>
      <div><b>Tickets</b>${r.tickets.slice().reverse().slice(0,12).map(t=>`<div class="lr" style="padding:6px 0"><div class="cell2"><span class="ln">${esc(paddleName(e,t.paddle))}</span><span class="ls">${t.qty} ticket${t.qty===1?'':'s'} · ${t.from===t.to?'#'+t.from:'#'+t.from+'–'+t.to}</span></div><b class="lnet">${fmt2(n0(r.price)*t.qty)}</b></div>`).join('')||'<p class="muted">None sold yet.</p>'}${r.tickets.length>12?`<p class="muted">… ${r.tickets.length-12} more</p>`:''}</div></div>
      ${r.log.length?`<p class="muted" style="padding:0 22px 14px;font-size:12.5px">${r.log.map(x=>esc(x.txt)).join(' · ')}</p>`:''}</div>`; }).join('')||'<div class="card"><div class="empty"><b>No raffles yet</b><span>A 50/50, a wine pull, a golf getaway — tickets sold by paddle, drawn with real randomness and a record of every draw.</span></div></div>');
  $('rfNew').onclick=()=>raffleDrawer(e,null); m.querySelectorAll('[data-rfe]').forEach(x=>x.onclick=()=>raffleDrawer(e,e.raffles.find(r=>r.id===x.dataset.rfe))); m.querySelectorAll('[data-rfs]').forEach(x=>x.onclick=()=>raffleSellDrawer(e,e.raffles.find(r=>r.id===x.dataset.rfs))); m.querySelectorAll('[data-rfd]').forEach(x=>x.onclick=()=>raffleDraw(e,e.raffles.find(r=>r.id===x.dataset.rfd)));
  m.querySelectorAll('[data-rfl]').forEach(x=>x.onclick=()=>raffleLock(e,e.raffles.find(r=>r.id===x.dataset.rfl))); m.querySelectorAll('[data-rfu]').forEach(x=>x.onclick=()=>raffleUnlock(e,e.raffles.find(r=>r.id===x.dataset.rfu))); m.querySelectorAll('[data-rfr]').forEach(x=>x.onclick=()=>raffleRecordPDF(e,e.raffles.find(r=>r.id===x.dataset.rfr)));
  m.querySelectorAll('[data-rfv]').forEach(x=>x.onclick=ev=>{ ev.preventDefault(); const [rid,pid]=x.dataset.rfv.split('|'); raffleVoid(e,e.raffles.find(r=>r.id===rid),pid); }); }
/* legitimacy, as the 50/50: the list is locked (a SHA-256 fingerprint of every ticket) before a draw, the draw refuses a list that
   changed, a void or an unlock needs a reason and is logged, and the official record carries all of it */
const raffleCanon=r=>r.tickets.map(t=>`${t.paddle}|${t.from}|${t.to}`).sort().join('\n')+'#'+n0(r.price);
async function raffleFP(r){ return (await sha256hex(raffleCanon(r))).toUpperCase(); }
async function raffleLock(e,r){ if(!r.tickets.length){ toast('No tickets sold yet'); return; } if(!crypto.subtle){ toast('Locking needs https'); return; } const fp=await raffleFP(r), count=r.tickets.reduce((a,t)=>a+t.qty,0); r.locked={at:new Date().toISOString(),fp,count}; r.log.push({at:r.locked.at,txt:`Locked ${count} tickets · fingerprint ${fp.slice(0,16)}`}); persist(); pushFund(e); render(); }
function raffleUnlock(e,r){ const why=prompt('Unlock the ticket list? Say why — it goes on the record.'); if(!why||!why.trim()) return; r.log.push({at:new Date().toISOString(),txt:`Unlocked: ${why.trim()}`}); r.locked=null; persist(); pushFund(e); render(); }
function raffleVoid(e,r,pid){ const p=r.prizes.find(x=>x.id===pid); if(!p||!p.winner) return; const why=prompt(`Void the draw for “${p.name}” (ticket ${p.winner.ticket}, ${p.winner.name})? Say why — it goes on the record.`); if(!why||!why.trim()) return; r.log.push({at:new Date().toISOString(),txt:`Voided ${p.name}: ticket #${p.winner.ticket} (${p.winner.name}) — ${why.trim()}`}); p.winner=null; persist(); pushFund(e); render(); }
